"""efe_robot: the efe-robot tools as Python functions (mode standard-mcp-shell; generated by
embodied_first_exam/standard/mcp/client_gen.py for this robot -- do not edit).

Each function sends the tool call of the same name, with the same arguments, to the efe-robot MCP server (the server
your MCP tools use: python3 /opt/tools/efe_mcp/server.py, started here as its own process on first use) and returns
the tool's JSON result as a dict. A call still running when its result is due ({"pending": true, "operation": id}) is
waited for here, so every function returns the final result. A tool error raises ToolError (its .payload is the
error JSON). Images are files under /app/obs/ (the result gives their paths); `inline_cameras` has no effect here.

    import efe_robot as R                      # /opt/tools is on PYTHONPATH
    R.describe_robot()
    R.observe(cameras=["head"], depth=True)
    R.move_robot(goals=[{"target": "left", "gripper": 1.0}])

Command line: python3 /opt/tools/efe_robot.py <tool> ['<JSON arguments>']   (prints the result)
"""
from __future__ import annotations
import importlib.util, json, os, pathlib, sys

SERVER = os.environ.get("EFE_MCP_SERVER", "/opt/tools/efe_mcp/server.py")
TOOLS = json.loads('{"spec": {"description": "The sport (`game spec`): actions (types, fields, ranges), cameras with their intrinsics and poses, units, rules, timing. Saved whole as a JSON file under /app/obs/ (`spec_file`, read it with your file"}, "status": {"description": "The current state, no images (`game status`)."}, "start": {"description": "You are ready (`game start`); the match begins when every seat has started."}, "observe": {"description": "The state and the camera images (`game observe`). The image is written as PNG files under /app/obs/: the whole view, and one file per tile at its native size (pixel coordinates in a tile file are that"}, "act": {"description": "One action (`game act JSON`): an object with `type` and the fields `spec` lists for it (the sport\'s shortcuts are actions of that type). A refused action returns the service\'s error (400: invalid, not"}, "wait": {"description": "Let the world run for `seconds` of game time (at most 10; `game wait DT` in steps of at most 1 s). It stops early when the world freezes for a review or the match ends. Also collects a pending operati"}, "ready": {"description": "Your review (`game ready \\"WHY\\" \\"PLAN\\"`): why you played as you did and your plan, each at most 2000 characters."}}')
_client = None


class ToolError(RuntimeError):
    def __init__(self, payload):
        super().__init__(payload.get("error") if isinstance(payload, dict) else str(payload))
        self.payload = payload


def _mcp():
    global _client
    if _client is None:
        spec = importlib.util.spec_from_file_location("efe_mcp_client", pathlib.Path(SERVER).parent / "mcp_client.py")
        mod = importlib.util.module_from_spec(spec)
        spec.loader.exec_module(mod)
        env = {"EFE_MCP_VIA": "python", "EFE_MCP_FILE_TAG": "py"}
        _client = (mod, mod.McpClient(cmd=[sys.executable, SERVER], env=env))
    return _client


def call(tool: str, **arguments) -> dict:
    """The tool `tool` with these arguments (None values left out); the final result as a dict."""
    if tool not in TOOLS:
        raise ValueError(f"no tool {tool!r}; tools: {', '.join(TOOLS)}")
    mod, c = _mcp()
    args = {k: v for k, v in arguments.items() if v is not None}
    try:
        return c.call(tool, **args)
    except mod.McpToolError as e:
        raise ToolError(e.payload) from None


def close():
    global _client
    if _client is not None:
        _client[1].close()
        _client = None

def spec() -> dict:
    """The sport (`game spec`): actions (types, fields, ranges), cameras with their intrinsics and poses, units, rules,
    timing. Saved whole as a JSON file under /app/obs/ (`spec_file`, read it with your file-reading tool); returned
    inline too when it is small.
    """
    return call('spec')


def status() -> dict:
    """The current state, no images (`game status`).
    """
    return call('status')


def start() -> dict:
    """You are ready (`game start`); the match begins when every seat has started.
    """
    return call('start')


def observe(*, query=None, inline_tiles=None) -> dict:
    """The state and the camera images (`game observe`). The image is written as PNG files under /app/obs/: the whole
    view, and one file per tile at its native size (pixel coordinates in a tile file are that camera's own image
    coordinates). The result lists the tiles (camera, frame, size, file); `inline_tiles` returns those tiles (by
    index) in the result as images.

    Arguments:
      query (dict): the sport's observe query, if `spec` describes one
      inline_tiles (list[int]): indices of tiles to return as images in the result [maxItems 8]
    """
    return call('observe', query=query, inline_tiles=inline_tiles)


def act(action) -> dict:
    """One action (`game act JSON`): an object with `type` and the fields `spec` lists for it (the sport's shortcuts
    are actions of that type). A refused action returns the service's error (400: invalid, nothing happens; 409: not
    now).

    Arguments:
      action (dict, required): the action, e.g. {"type": ...}
    """
    return call('act', action=action)


def wait(*, seconds=None, operation=None) -> dict:
    """Let the world run for `seconds` of game time (at most 10; `game wait DT` in steps of at most 1 s). It stops
    early when the world freezes for a review or the match ends. Also collects a pending operation (`operation`).

    Arguments:
      seconds (float): game seconds to let pass (default 0.1) [minimum 0.01, maximum 10.0]
      operation (str): a pending operation's id
    """
    return call('wait', seconds=seconds, operation=operation)


def ready(why, plan) -> dict:
    """Your review (`game ready "WHY" "PLAN"`): why you played as you did and your plan, each at most 2000 characters.

    Arguments:
      why (str, required):
      plan (str, required):
    """
    return call('ready', why=why, plan=plan)


def _main(argv):
    if not argv or argv[0] in ("-h", "--help"):
        print(__doc__)
        print("tools:", ", ".join(TOOLS))
        return 0
    args = json.loads(argv[1]) if len(argv) > 1 else {}
    try:
        out = call(argv[0], **args)
    except ToolError as e:
        print(json.dumps(e.payload, indent=1))
        return 1
    finally:
        close()
    print(json.dumps(out, indent=1))
    return 0


if __name__ == "__main__":
    sys.exit(_main(sys.argv[1:]))
